data.query:
query Order($where: OrderWhereInput, $orderBy: [OrderOrderByInput!], $first: Int, $after: String) {
  order(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        orderLines {
          edges {
            node {
              orderLineReleases {
                total
                edges {
                  node {
                    id
                    quantity {
                      value
                      unitId
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

data.mutation:
mutation CreateShipmentLine($payload: [ShipmentLineCreatePayloadInput!]!) {
  createShipmentLine(payload: $payload) {
    id
    orderLineReleaseId
    shipmentId
    quantity {
      value
      unitId
    }
  }
}

data.responseTransform:
